"""Freeze source-based L09 review without modifying authored questions or bank."""
import collections,datetime,hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'))
from validate import question_hash,CHECK_KEYS
load=lambda p:json.loads((ROOT/p).read_text())
blindpath=ROOT/'audits/blind-answers-W02-L09-independent.json';blind=load(blindpath);assert blind['complete'] and blind['solvedBeforeAnswerSeen'] and not blind['keyedBatchOpened']
packet=load('audits/blind-W02-L09-review-copy.json');batch=load('data/question-batches/W02-L09.json');answers={a['questionId']:a for a in blind['answers']};qs={q['id']:q for q in batch['questions']}
assert len(answers)==len(qs)==102
for q in packet['questions']:
 for key in ['stem','version','selectionMode','options','assumptions','difficulty']:assert q[key]==qs[q['id']][key]
 assert set(qs[q['id']]['correctOptionIds'])==set(answers[q['id']]['independentAnswerOptionIds'])
flags={}
